const owner = "alice";
const token = (process.env.PI_API_TOKENS ?? "").split(/[\n,]/).map((l) => l.split(":")).find(([o]) => o === owner)?.slice(1).join(":");
if (!process.argv[2]) throw new Error("pass a test owner/repo argument");
const base = "http://127.0.0.1:8080";
const h = { authorization: `Bearer ${token}`, "content-type": "application/json" };
await Promise.all(briefs.map(async (b) => {
  const t0 = Date.now();
  try {
    const r = await fetch(`${base}/sessions`, { method: "POST", headers: h, body: JSON.stringify({ provider: "openai-codex", model: "gpt-6.1-terra", repo: process.argv[2] }) });
    const s = await r.json(); const t1 = Date.now();
    if (r.status !== 201) { console.log(`${b.label} ERROR create=${r.status} ${JSON.stringify(s)}`); return; }
    const p = await fetch(`${base}/sessions/${s.sessionId}/events`, { method: "POST", headers: h, body: JSON.stringify({ kind: "message", text: b.text }) });
    console.log(`${b.label} ${s.sessionId} ${t1 - t0} ${Date.now() - t1} post=${p.status}`);
  } catch (e) { console.log(`${b.label} ERROR ${String(e.message).slice(0, 80)}`); }
}));
